```openscad
// T-shaped extrusion nut - rides in the slot of an aluminium extrusion
// Print orientation: bottom flange on the bed (z = 0), neck pointing up.
// The profile is centred on the origin in X and Y.

$fn = 64;

// ---- Dimensions (mm) ----
profile_len    = 10;    // length of the T along X
flange_w       = 12;    // width of the bottom flange (Y)
flange_t       = 2.5;   // thickness of the flange (Z)
neck_w         = 6;     // width of the neck above the flange
neck_top_z     = 5.5;   // height of the neck top face
screw_d        = 3.4;   // diameter of the central screw hole
eps            = 0.5;   // overshoot for clean boolean cuts

// ---- Derived ----
neck_h = neck_top_z - flange_t;  // height of the neck alone (3.0)

module t_profile() {
    // Bottom flange
    translate([-profile_len/2, -flange_w/2, 0])
        cube([profile_len, flange_w, flange_t]);
    // Neck, centred on the flange
    translate([-profile_len/2, 0, flange_t])
        cube([profile_len, neck_w, neck_h]);
}

difference() {
    // Solid part
    linear_extrude(height = neck_top_z)
        t_profile();

    // Vertical screw hole through the centre
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_top_z + 2*eps);
}
```

