// T-shaped nut for aluminium extrusion slot
// Print orientation: flange down on bed, neck up

// ---- Dimensions (mm) ----
profile_len    = 10;   // length along X
flange_w       = 12;   // flange width (Y)
flange_t       = 2.5;  // flange thickness (Z), z = 0..2.5
neck_w         = 6;    // neck width (Y)
neck_top_z     = 5.5;  // top of neck (Z)
screw_d        = 3.4;  // screw hole diameter
eps            = 0.5;  // cut overshoot

// ---- Model ----
difference() {
    // Upside-down T profile, centred in X and Y
    union() {
        translate([-profile_len/2, -flange_w/2, 0])
            cube([profile_len, flange_w, flange_t]);   // flange
        translate([-profile_len/2, 0, flange_t])
            cube([profile_len, neck_w, neck_top_z - flange_t]); // neck
    }
    // Vertical screw hole through the part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_top_z + 2*eps, $fn = 64);
}
