```openscad
// T-shaped nut for aluminium extrusion slot
// Print orientation: flange on bed (z = 0), neck pointing up (+Z)

$fn = 64;

// ---- Dimensions (mm) ----
profile_len    = 12;    // length along X axis
flange_w       = 14;    // flange width (Y)
flange_t       = 2.5;   // flange thickness (Z), z = 0 to 2.5
neck_w         = 7;     // neck width (Y), centred on flange
total_h        = 5.5;   // neck top height (Z)
hole_d         = 4.5;   // screw hole diameter
eps            = 0.5;   // cutter overshoot past faces

// ---- Model ----
difference() {
    union() {
        // Bottom flange
        translate([-profile_len/2, -flange_w/2, 0])
            cube([profile_len, flange_w, flange_t]);
        // Neck (overlaps flange in volume, keeps profile clean)
        translate([-profile_len/2, -neck_w/2, flange_t])
            cube([profile_len, neck_w, total_h - flange_t]);
    }
    // Vertical screw hole through the centre
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = total_h + 2*eps);
}
