```openscad
// Stiffened cover panel: flat plate with 3 longitudinal ribs
// Units: mm. Print orientation: plate flat on bed, ribs pointing up (+Z).

// ---------------- Parameters ----------------
plate_len    = 120;   // plate length along X
plate_wid    = 80;    // plate width along Y
plate_thk    = 3;     // plate thickness (z = 0 to 3)

rib_thk      = 3;     // rib thickness along X
rib_h        = 5;     // rib height above plate (z = 3 to 8)
rib_count    = 3;     // number of ribs
rib_pitch    = 30;    // centre-to-centre spacing of ribs along X
rib_offset   = 30;    // distance of outer ribs from plate ends

eps          = 0.5;   // overlap/overlap past for clean booleans

$fn = 64;

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running full width along Y, standing on the plate
    for (i = [0 : rib_count - 1]) {
        x_c = (i < rib_count - 1) ? (rib_offset + i * rib_pitch) : -rib_offset;
        translate([x_c - rib_thk/2, 0, plate_thk])
            cube([rib_thk, plate_wid, rib_h]);
    }
}
```

