```openscad
// T-shaped extrusion nut - slides into the slot of an aluminium extrusion
// Print orientation: flat on bed, flange down (z = 0 up to flange thickness)

// ---------------- Parameters ----------------
profile_len   = 12;    // length along X axis (mm)
flange_w      = 10;    // flange width along Y (mm)
flange_t      = 3;     // flange thickness (mm), z = 0 .. 3
neck_w        = 7;     // neck width along Y (mm)
neck_top_z    = 6;     // top of neck (mm), z = 3 .. 6
screw_d       = 4.5;   // central screw hole diameter (mm)
eps           = 0.5;   // cutter overshoot past faces (mm)
$fn           = 96;    // curve resolution

// Derived
total_h = neck_top_z;  // 6 mm overall height

// ---------------- Model ----------------
difference() {
    // Upside-down T profile, centred in X and Y
    union() {
        // Bottom flange
        translate([-profile_len/2, -flange_w/2, 0])
            cube([profile_len, flange_w, flange_t]);
        // Neck (overlaps flange slightly so the union is one solid)
        translate([-profile_len/2, 0, flange_t - 0.01])
            cube([profile_len, neck_w, neck_top_z - flange_t + 0.01]);
    }

    // Vertical screw hole through the centre
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = total_h + 2*eps);
}
