```openscad
// T-shaped extrusion nut
// Print orientation: flange on the bed (z = 0), neck pointing up (+Z)

// ---------------- Parameters ----------------
profile_len   = 12;    // profile length along X (mm)
flange_w      = 10;    // flange width along Y (mm)
flange_t      = 3;     // flange thickness (mm), z = 0..3
neck_w        = 7;     // neck width along Y (mm)
neck_top_z    = 6;     // top of neck (mm), neck runs z = 3..6
screw_d       = 4.5;   // screw hole diameter (mm)
eps           = 0.5;   // cutter overshoot past faces (mm)
$fn           = 96;    // curve resolution

// Derived
overlap = 0.01;        // small overlap so flange and neck fuse cleanly

// ---------------- Model ----------------
difference() {
    union() {
        // Bottom flange
        translate([-profile_len/2, -flange_w/2, 0])
            cube([profile_len, flange_w, flange_t]);
        // Neck (upside-down T), centred on the flange
        translate([-profile_len/2, -neck_w/2, flange_t - overlap])
            cube([profile_len, neck_w, neck_top_z - flange_t + overlap]);
    }
    // Vertical screw hole through the full height
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_top_z + 2*eps);
}
