```openscad
// Flat dial ring with radial tick marks for a rotary stage
// Print orientation: flat on bed, top face (with grooves) facing up

// ---------- Parameters ----------
outer_d      = 60;    // ring outer diameter
inner_d      = 40;    // ring inner diameter
thickness    = 3;     // ring thickness (Z)
tick_count   = 12;    // number of tick marks
tick_w       = 1.5;   // tick width
tick_depth   = 1;     // tick depth from top face
tick_start_a = 0;     // start angle of first tick (deg, +X axis)
eps          = 0.5;   // cutter overshoot past faces

$fn = 128;

// ---------- Model ----------
difference() {
    // Ring body
    cylinder(d = outer_d, h = thickness);

    // Central bore
    translate([0, 0, -eps])
        cylinder(d = inner_d, h = thickness + 2 * eps);

    // Radial tick grooves, cutter centred on outer edge
    for (i = [0 : tick_count - 1]) {
        a = tick_start_a + i * 360 / tick_count;
        translate([outer_d / 2, 0, thickness - tick_depth])
            rotate([0, 0, a])
                linear_extrude(height = tick_w)
                    circle(r = thickness - tick_depth + eps);
    }
}
```

