```openscad
// Stiffened cover panel: flat plate with 4 ribs along Y
// Units: mm. Print orientation: plate flat on bed, ribs upward.

// ---------- Parameters ----------
plate_len   = 120;   // plate length along X
plate_wid   = 60;    // plate width along Y
plate_thk   = 2;     // plate thickness (z = 0 to 2)

rib_thk     = 3;     // rib thickness along X
rib_h       = 6;     // rib height above plate (z = 2 to 8)
rib_count   = 4;     // number of ribs
rib_pitch   = 24;    // centre-to-centre spacing of ribs along X

eps         = 0.5;   // overlap for clean unions / fused corners

$fn = 64;

// ---------- Derived ----------
first_x = -(rib_count - 1) * rib_pitch / 2;  // centres at -36, -12, 12, 36

// ---------- Model ----------
union() {
    // Base plate, centred in X and Y
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running the full width along Y
    for (i = [0 : rib_count - 1]) {
        translate([first_x + i * rib_pitch - rib_thk / 2, 0, plate_thk - eps])
            cube([rib_thk, plate_wid, rib_h + eps]);
    }
}
```

