// Cabinet door pull handle
// Print orientation: posts on bed (z = 0), bar on top (z = 25 to 33)

// ---- Dimensions (mm) ----
post_d        = 12;    // post diameter
post_h        = 25;    // post height (z = 0 to 25)
bar_len       = 76;    // bar length along X
bar_w         = 12;    // bar width along Y
