    // Posts
    for (sx = [-32, 32]) {
        difference() {
            cylinder(d = post_d, h = post_h);
            translate([sx, 0, -eps])
                cylinder(d = screw_d, h = screw_depth + 2 * eps);
        }
    }
    // Bar
    translate([-bar_len / 2, -bar_w / 2, post_h])
        cube([bar_len, bar_w, bar_t]);
}
