// Stiffened cover panel
// Print orientation: plate flat on bed, ribs pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 80;    // plate length along X (mm)
plate_wid   = 80;    // plate width along Y (mm)
plate_thk   = 3;     // plate thickness (mm), z = 0..3

rib_count   = 4;     // number of ribs
rib_thk     = 2;     // rib thickness along X (mm)
rib_h       = 4;     // rib height above plate (mm), z = 3..7
rib_pitch   = 16;    // centre-to-centre spacing of ribs along X (mm)

eps         = 0.5;   // overlap of ribs into plate for a clean union (mm)
$fn         = 64;    // curve resolution (no curves here, set per convention)

// ---------- Derived ----------
plate_x0 = -plate_len/2 + rib_thk/2;   // plate starts where first rib begins
plate_x2 = plate_len - plate_x0;       // plate ends where last rib ends

// ---------- Model ----------
union() {
    // Base plate, centred in Y, shifted in X per the rib layout
    translate([plate_x0, -plate_wid/2, 0])
        cube([plate_x2, plate_wid, plate_thk]);

    // Ribs running full width along Y, overlapping into the plate
    for (i = [0 : rib_count - 1]) {
        translate([(i - (rib_count - 1)/2) * rib_pitch - rib_thk/2,
                   -plate_wid/2,
                   plate_thk - eps])
            cube([rib_thk, plate_wid, rib_h + eps]);
    }
}
