rib_count   = 3;    // number of ribs
rib_pitch   = 20;   // centre-to-centre spacing of ribs (mm)

eps         = 0.5;  // overlap/merge tolerance (mm)
$fn         = 64;   // curve resolution

// ---------- Derived ----------
