// ---------- Model ----------
union() {
    // Base plate
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, standing on the plate (slight overlap into plate for clean union)
    for (i = [0 : rib_count - 1]) {
        x = -plate_len / 2 + rib_thk / 2 + i * rib_pitch;
        translate([x, -rib_wid / 2, plate_thk - eps])
            cube([rib_thk, rib_wid, rib_h + eps]);
