// T-shaped extrusion nut - rides in the slot of an aluminium extrusion
// Print orientation: bottom flange on the bed (z = 0), neck pointing up.
// The profile is centred on the origin in X and Y.

$fn = 64;

// ---- Dimensions (mm) ----
profile_len    = 12;    // length along X
flange_w       = 14;    // bottom flange width (Y)
flange_t       = 2.5;   // flange thickness (Z)
neck_w         = 7;     // neck width (Y)
neck_top_z     = 5.5;   // height of the top of the neck
screw_d        = 3.4;   // through-hole diameter for the screw
eps            = 0.5;   // cutter overshoot past faces

// ---- Model ----
difference() {
    union() {
        // Bottom flange: z = 0 .. flange_t
        translate([-profile_len / 2, -flange_w / 2, 0])
            cube([profile_len, flange_w, flange_t]);

        // Neck, centred on the flange, running from flange_t up to neck_top_z
        translate([-neck_w / 2, 0, flange_t])
            cube([neck_w, flange_w, neck_top_z - flange_t]);
    }

    // Vertical through-hole, centred on the part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_top_z + 2 * eps);
}
