// Stiffened cover panel: flat plate with 3 longitudinal ribs
// Print orientation: plate flat on bed, ribs pointing up (+Z)

// ---------------- Parameters ----------------
plate_len    = 120;   // plate length along X (mm)
plate_wid    = 60;    // plate width along Y (mm)
plate_thk    = 3;     // plate thickness (mm), z = 0..3

rib_thk      = 2;     // rib thickness along X (mm)
rib_h        = 5;     // rib height above plate (mm), z = 3..8
rib_count    = 3;     // number of ribs
rib_pitch    = 30;    // centre-to-centre spacing of ribs (mm)

eps          = 0.5;   // overlap/merge tolerance (mm)
$fn          = 64;    // curve resolution (no curves here, set per rule)

// Derived
plate_z0     = 0;
plate_z1     = plate_thk;
rib_z0       = plate_z1 - eps;   // ribs start slightly inside plate top
rib_z1       = plate_z0 + plate_thk + rib_h;  // top of ribs (z = 8)

// Recessed area between outer ribs and plate ends (4 equal parts)
recess_w     = plate_wid / 4;    // width of each recess along Y

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, plate_z0])
        cube([plate_len, plate_wid, plate_z1]);

    // Ribs, centred on their pitch positions
    for (i = [0 : rib_count - 1]) {
        x_c = (i - (rib_count - 1)/2) * rib_pitch;
        translate([x_c - rib_thk/2, -plate_wid/2, rib_z0])
            cube([rib_thk, plate_wid, rib_z1]);
    }

    // Recesses between outer ribs and plate ends
    for (s = [-1, 1]) {
        translate([s * (plate_len/2 - rib_pitch/2) - rib_thk/2,
                   -plate_wid/2, plate_z0])
            cube([rib_thk, recess_w, plate_z1]);
    }
}
