// Cable bridge for bench mat - rectangular block with a semicircular tunnel along Y
// Units: mm. Print orientation: base on bed (z = 0), centred on origin in X and Y.

// ---------------- Parameters ----------------
block_len    = 100;   // block length along X
block_wid    = 40;    // block width along Y
