tunnel_d     = 10;    // tunnel diameter (full cylinder)
tunnel_x     = 0;     // tunnel axis X position
tunnel_z     = 0;     // tunnel axis Z position (floor level)

overcut      = 0.5;   // extra length so cutters pass beyond the end faces
$fn          = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    // Main block
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // Semicircular tunnel: half of a cylinder whose axis lies along Y
    translate([tunnel_x, -block_wid / 2 - overcut, tunnel_z])
        rotate([90, 0, 0])
            cylinder(d = tunnel_d, h = block_wid + 2 * overcut);
}
