// Eccentric cam for a shaker mechanism
// Print orientation: disc flat on the bed, hub rising in +Z

// ---------------- Parameters ----------------
disc_d      = 50;    // cam disc diameter
disc_h      = 5;     // cam disc thickness
offset_x    = 6;     // disc centre X offset from shaft axis
offset_y    = 0;     // disc centre Y offset from shaft axis

hub_d       = 14;    // shaft hub diameter
hub_top_z   = 10;    // top of hub (hub rises 5 mm above disc)

shaft_hole  = 8;     // shaft through-hole diameter

eps         = 0.5;   // cutter overshoot past faces
$fn         = 128;   // curve resolution

// ---------------- Model ----------------
difference() {
    union() {
        // Cam disc, centred at (offset_x, offset_y, 0)
        translate([offset_x, offset_y, 0])
            cylinder(d = disc_d, h = disc_h);

        // Shaft hub, centred on the Z axis, from z = 5 to z = 10
        translate([0, 0, hub_top_z - hub_d / 2])
            cylinder(d = hub_d, h = hub_d);
    }

    // Shaft through-hole along the Z axis, through both disc and hub
    translate([0, 0, -eps])
        cylinder(d = shaft_hole, h = hub_top_z + 2 * eps);
}
