    union() {
        // Eccentric disc
        translate([offset_x, offset_y, 0])
            cylinder(d = disc_d, h = disc_h);

        // Hub around the shaft axis
        translate([0, 0, disc_h])
            cylinder(d = hub_d, h = hub_top_z - disc_h);
    }

    // Shaft through-hole on the Z axis, through hub and disc
    translate([0, 0, -eps])
        cylinder(d = shaft_hole_d, h = hub_top_z + 2 * eps);

    // Clear the disc area under the hub (hub is a separate solid)
    translate([0, 0, disc_h - eps])
        cylinder(d = hub_d + 2 * eps, h = eps);
}
